function sortStringsByLength(arr) {
    // Check if input is not an array
    if (!Array.isArray(arr)) throw new Error("Input is not an array");

    let sortedArr = [];

    try {
        // Iterate through each element in the array
        arr.forEach(element => {
            // Check if element is not a string
            if(typeof element !== "string") throw new TypeError(`Element ${element} is not a string`);

            // Create a temporary object with key as length of string and value as original element
            const tempObj = {length: element.length, original: element};

            // Push the temporary object into the sorted array
            sortedArr.push(tempObj);
